from unittest.mock import Mock


def load_temp(fetch, city):
    try:
        return fetch(city)["temp"]
    except ConnectionError:
        return None


ok = Mock(return_value={"temp": 12})
print(load_temp(ok, "Краков"))

broken = Mock(side_effect=ValueError("плохое значение"))
print(load_temp(broken, "Краков"))
